assert(pool:AppendToTimeline({{mediaPoolItem=clips[2],startFrame=0,endFrame=3779,mediaType=1,trackIndex=2,recordFrame=0}}))
if tl:GetTrackCount('audio')<1 then tl:AddTrack('audio','stereo')end
assert(pool:AppendToTimeline({{mediaPoolItem=clips[3],startFrame=0,endFrame=3779,mediaType=2,trackIndex=1,recordFrame=0}}));tl:SetTrackName('video',1,'Actual captures and title cards');tl:SetTrackName('video',2,'Munny dialogue and synchronized mouth');tl:SetTrackName('audio',1,'Babble, entrance and recorded app events');p:SetCurrentTimeline(tl);tl:SetCurrentTimecode('00:00:58:00');pm:SaveProject();assert(pm:ExportProject(p:GetName(),root..'resolve/Autoloot-Munny-Final-Practice-Demo.drp'))
local f=assert(io.open(root..'resolve/final-verification.txt','w'));f:write('Timeline: '..tl:GetName()..'\nFrames: '..(tl:GetEndFrame()-tl:GetStartFrame())..'\nV1 clips: '..#tl:GetItemListInTrack('video',1)..'\nV2 clips: '..#tl:GetItemListInTrack('video',2)..'\nA1 clips: '..#tl:GetItemListInTrack('audio',1)..'\n');f:close();r:OpenPage('edit')
